    foreach($nullableColumns as $table=>$columns)foreach($columns as $column=>$definition){$s=$pdo->prepare('SELECT IS_NULLABLE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? AND COLUMN_NAME=?');$s->execute(array($table,$column));if($s->fetchColumn()==='NO')$pdo->exec('ALTER TABLE '.$table.' MODIFY '.$column.' '.$definition.' NULL DEFAULT '.($table==='products'&&$column==='device_limit'?'1':'NULL'));}
