        'notifications'=>array('target_type'=>'VARCHAR(40) NULL','target_id'=>'BIGINT UNSIGNED NULL','dedupe_key'=>'VARCHAR(160) CHARACTER SET ascii COLLATE ascii_bin NULL'),
