    foreach($products as $product){$s=$pdo->prepare('SELECT id FROM product_plans WHERE product_id=? LIMIT 1');$s->execute(array($product['id']));if(!$s->fetch()){$name='默认方案';$s=$pdo->prepare('SELECT COUNT(*) FROM product_plans WHERE product_id=? AND name=?');$s->execute(array($product['id'],$name));if((int)$s->fetchColumn())$name='基础方案';$pdo->prepare('INSERT INTO product_plans(product_id,name,duration_days,price_cents,status,sort_order,created_at,updated_at) VALUES(?,?,?,? ,"active",0,NOW(),NOW())')->execute(array($product['id'],$name,$product['duration_days'],$product['price_cents']));}}
    // 只对完全没有映射的历史团回填，且在默认方案创建之后执行。
    $pdo->exec('INSERT INTO group_campaign_plans(campaign_id,product_plan_id,created_at) SELECT g.id,p.id,NOW() FROM group_campaigns g JOIN product_plans p ON p.product_id=g.product_id AND p.status="active" LEFT JOIN (SELECT DISTINCT campaign_id FROM group_campaign_plans) x ON x.campaign_id=g.id JOIN products product ON product.id=p.product_id AND product.product_type="vpn" WHERE g.flow_version=1 AND x.campaign_id IS NULL');
    $pdo->exec('UPDATE orders o JOIN product_plans p ON p.product_id=o.product_id AND p.duration_days=o.duration_days_snapshot AND p.price_cents=o.unit_price_cents_snapshot SET o.product_plan_id=p.id,o.plan_name_snapshot=p.name WHERE o.product_type_snapshot="vpn" AND (o.product_plan_id IS NULL OR o.plan_name_snapshot="")');
    $pdo->exec('UPDATE orders o JOIN product_plans p ON p.id=o.product_plan_id SET o.plan_name_snapshot=p.name WHERE o.product_type_snapshot="vpn" AND o.plan_name_snapshot=""');
